insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('2efecf97-4c19-5e74-bbef-707e2cef5285', 'T01', '銀座のおもてなし職人', '気づかれないほど自然な気配りが、最高のサービス。', '相手の表情や間の変化を読み、頼まれる前に必要なことを整える上質サービス型。目立つより、体験全体を滑らかにすることに喜びを感じる。', 'Hospitality Stars', 'H01 銀座の黒子', '{"先読み","落ち着き","高い接客基準"}', '{"自己犠牲になりやすい","成果が見えにくい"}', '{"高級店サービス","ホテルサービス","コンシェルジュ"}', '{"鮨","割烹","フレンチ","会員制"}', '{"シニアサービス","副支配人候補"}', 'Guest', 'Craft', 'High-end', 'Specialist', 'Arrange', 'Intuitive');
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('27c1b7be-4235-5d37-af85-a48165f34686', 'T02', 'サービス分析官', 'おもてなしを、感覚だけで終わらせない。', '顧客満足や導線を観察・分析し、再現性のあるサービスへ落とし込む改善型。', 'Hospitality Stars', 'H01 銀座の黒子', '{"観察力","改善力","再現性"}', '{"数字に寄りすぎる","現場の温度感を失いやすい"}', '{"CX改善","サービス品質管理","研修企画"}', '{"ホテル","高級レストラン","大型店"}', '{"サービス企画","品質責任者"}', 'Guest', 'Craft', 'High-end', 'Specialist', 'Arrange', 'Data');
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('05507a6b-6bc7-5ef8-a004-043ccafbbcf7', 'T03', '接客革命家', '『普通の接客』を、もっと面白く。', '既存の接客常識にとらわれず、会話・演出・デジタルを使って新しい顧客体験を生み出す。', 'Hospitality Stars', 'H03 空気の演出家', '{"発想力","行動力","顧客理解"}', '{"やりすぎて好みが分かれる","標準化が弱い"}', '{"体験企画","イベント接客","SNS連動企画"}', '{"エンタメレストラン","カフェ","バー"}', '{"CX企画","新店立ち上げ"}', 'Guest', 'Craft', 'High-end', 'Specialist', 'Venture', 'Intuitive');
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('d4966310-492f-547e-8f82-549fab177b7c', 'T04', 'CXストラテジスト', '顧客体験を、事業の成長エンジンに。', '来店前から退店後までの体験を設計し、ブランド価値と収益へつなげる戦略型。', 'Hospitality Stars', 'B01 ブランド創造者', '{"顧客設計","ブランド視点","分析力"}', '{"現場負荷を見落としやすい","設計が複雑化しやすい"}', '{"CX責任者","ブランド企画","CRM"}', '{"高級業態","ホテル","複合施設"}', '{"CX責任者","事業企画"}', 'Guest', 'Craft', 'High-end', 'Specialist', 'Venture', 'Data');
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('441278c2-75b0-5f74-be5c-dfc90aa01603', 'T05', '銀座支配人', '一人のお客様と、店全体を同時に見る。', '上質な接客を自ら体現しながら、サービスチーム全体を統率する現場リーダー。', 'Hospitality Stars', 'L01 現場司令官', '{"統率力","顧客対応","危機管理"}', '{"抱え込みやすい","部下に高基準を求めすぎる"}', '{"支配人","サービスマネージャー"}', '{"高級店","ホテル","会員制"}', '{"支配人","店舗責任者"}', 'Guest', 'Craft', 'High-end', 'Leader', 'Arrange', 'Intuitive');
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('dbb9f32c-5287-5857-b4b9-bc35dd5b6c90', 'T06', 'ラグジュアリー統括官', '上質さを、複数店舗で再現する。', '一店舗の成功を基準・教育・監査へ落とし込み、複数店のサービス品質を統括する。', 'Hospitality Stars', 'L04 改善プロデューサー', '{"標準化","教育","多店舗管理"}', '{"現場との距離が開きやすい","ルール過多になりやすい"}', '{"サービス統括","教育責任者","SV"}', '{"ホテル","高級チェーン","百貨店"}', '{"統括責任者","SV"}', 'Guest', 'Craft', 'High-end', 'Leader', 'Arrange', 'Data');
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('c09c387a-b67a-59da-a08f-d3e7668f2354', 'T07', 'ホスピタリティ開拓者', 'まだない『喜ばせ方』をつくる。', '新しい土地・業態・顧客層でも、人を喜ばせる方法を探し、現場から体験を開拓する。', 'Hospitality Stars', 'G01 挑戦者', '{"適応力","共感力","挑戦心"}', '{"準備不足","再現性が弱い"}', '{"新店立ち上げ","海外店","イベント"}', '{"新業態","観光地","海外"}', '{"立ち上げメンバー","サービス責任者"}', 'Guest', 'Craft', 'High-end', 'Leader', 'Venture', 'Intuitive');
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('d21e7413-df73-5200-8830-25970f623753', 'T08', 'ホスピタリティCEO', '人を喜ばせる文化を、会社の競争力に。', '顧客・従業員・ブランドを一体で捉え、ホスピタリティを企業文化と収益へ変える経営型。', 'Hospitality Stars', 'B05 食文化プロデューサー', '{"経営視点","文化づくり","長期設計"}', '{"理想が大きくなりやすい","現場の細部を見失いやすい"}', '{"経営者","ブランドCEO","事業責任者"}', '{"高級グループ","ホテル","複数ブランド"}', '{"CEO","事業本部長"}', 'Guest', 'Craft', 'High-end', 'Leader', 'Venture', 'Data');
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('9637d169-29cf-5d44-a066-cae4768094f6', 'T09', '愛されホールスタッフ', '名前を覚えられるより、相手を覚えている。', '親しみやすさと気配りで、お客様がまた会いに来たくなる関係をつくる。', 'Community Hosts', 'H05 常連メーカー', '{"親近感","関係構築","会話力"}', '{"常連を優先しすぎる","距離が近くなりすぎる"}', '{"ホール","カフェスタッフ","居酒屋接客"}', '{"居酒屋","カフェ","地域店"}', '{"ホールリーダー"}', 'Guest', 'Craft', 'Mass', 'Specialist', 'Arrange', 'Intuitive');
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('ada9def9-02f2-5505-ab89-ce783267aba9', 'T10', '接客オペレーター', '忙しくても、誰にでも心地よい接客を。', 'スピードと親しみを両立し、誰が担当しても一定品質の接客を実現する。', 'Community Hosts', 'C04 再現の達人', '{"安定運営","効率","接客基準"}', '{"個別対応が弱くなりやすい","柔軟性不足"}', '{"接客トレーナー","オペレーション"}', '{"ファミレス","フードコート","チェーン"}', '{"トレーナー","時間帯責任者"}', 'Guest', 'Craft', 'Mass', 'Specialist', 'Arrange', 'Data');
