insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6) values ('3721ae6c-5669-5f0b-b47a-e4b4ca127271', 'T53', 'ブランド統括プロデューサー', '複数の商品を、一つの憧れにまとめる。', '商品、店舗、広告、コラボを統括し、ブランド全体の価値を高める。', 'Premium Producers', 'B01 ブランド創造者', '{"統合力","審美眼","統率"}', '{"現場負荷","個別商品の弱体化"}', '{"ブランド統括","クリエイティブ責任者"}', '{"高級食品","複数ブランド"}', '{"ブランドディレクター"}', 'Product', 'Business', 'High-end', 'Leader', 'Arrange', 'Intuitive');
